#!/usr/bin/env node

/**
 * generate-latex.mjs — Validate and compile a generated .tex CV file to PDF
 *
 * Usage:
 *   node generate-latex.mjs <input.tex> [output.pdf]
 *
 * Reads the .tex file, validates structure, compiles to PDF via tectonic or pdflatex.
 * If output.pdf is omitted, writes to the same directory as input with .pdf extension.
 * The .tex file is generated by the AI agent using templates/cv-template.tex.
 *
 * Requires: tectonic (preferred, brew install tectonic) or pdflatex (MiKTeX / TeX Live) on PATH.
 */

import { readFile, writeFile, stat, copyFile, rm, mkdtemp } from 'fs/promises';
import { resolve, basename, dirname, join } from 'path';
import { execFileSync } from 'child_process';
import { existsSync, mkdirSync } from 'fs';
import { constants } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import { assertWritableOutput } from './output-safety.mjs';
import { claimRenderOptions, enforceRenderedCvClaims, extractDocumentSegments } from './validate-cv-claims.mjs';

const PROJECT_ROOT = dirname(fileURLToPath(import.meta.url));
const COPYFILE_EXCL = constants.COPYFILE_EXCL;

// The template emits 4 sections (Education, Work Experience, Personal
// Projects, Technical Skills). We count \section{} blocks rather than match
// the English titles, so a localized CV (e.g. "Educación", "学歴") still
// validates instead of failing with a spurious "Missing section".
const MIN_SECTIONS = 4;

const REQUIRED_COMMANDS = [
  '\\\\resumeSubheading',
  '\\\\resumeItem',
  '\\\\resumeProjectHeading',
];

// CJK (Japanese/Chinese/Korean) ranges: Hiragana, Katakana, CJK ideographs,
// compatibility ideographs, halfwidth katakana, and Hangul. The template is a
// pdfLaTeX/Computer-Modern setup with no CJK font, so these glyphs cannot
// render under pdflatex or tectonic — detect them and fail with guidance
// instead of emitting a broken PDF / cryptic compile log.
const CJK_RE = /[぀-ヿ㐀-鿿豈-﫿ｦ-ﾟ가-힯ᄀ-ᇿ]/;

async function main() {
  const { args, options: claimOptions } = claimRenderOptions(process.argv.slice(2));
  const [inputPath, outputPath] = args;
  if (!inputPath) {
    console.error('Usage: node generate-latex.mjs <input.tex> [output.pdf] [--cv-source cv.md] [--anchors manifest.json] [--allow-unverified-claims]');
    process.exit(1);
  }

  const absPath = resolve(inputPath);
  const texDir = dirname(absPath);
  const texBase = basename(absPath, '.tex');
  const defaultPdf = join(texDir, `${texBase}.pdf`);
  let targetPdf;
  try {
    targetPdf = assertWritableOutput(outputPath ? resolve(outputPath) : defaultPdf, { root: PROJECT_ROOT });
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  let content;
  try {
    content = await readFile(absPath, 'utf-8');
  } catch (err) {
    console.error(`Error reading ${absPath}: ${err.message}`);
    process.exit(1);
  }

  const issues = [];

  // Check section count (language-agnostic — see MIN_SECTIONS).
  const sectionCount = (content.match(/\\section\{/g) || []).length;
  if (sectionCount < MIN_SECTIONS) {
    issues.push(`Expected at least ${MIN_SECTIONS} \\section{} blocks (Education, Work Experience, Projects, Skills — or localized equivalents), found ${sectionCount}`);
  }

  // The template cannot render CJK; fail with guidance instead of a broken PDF.
  if (CJK_RE.test(content)) {
    issues.push('CJK characters detected. The LaTeX template does not support Japanese/Chinese/Korean yet (pdfLaTeX setup with no CJK font). Use `pdf` mode (HTML to PDF, which renders CJK) for these CVs.');
  }

  // Check required commands are used
  for (const cmd of REQUIRED_COMMANDS) {
    if (!new RegExp(cmd).test(content)) {
      issues.push(`Missing command: ${cmd}`);
    }
  }

  // Check document structure
  if (!content.includes('\\begin{document}')) {
    issues.push('Missing \\begin{document}');
  }
  if (!content.includes('\\end{document}')) {
    issues.push('Missing \\end{document}');
  }

  // Check for unresolved placeholders
  const unresolvedMatch = content.match(/\{\{[A-Z_]+\}\}/g);
  if (unresolvedMatch) {
    issues.push(`Unresolved placeholders: ${[...new Set(unresolvedMatch)].join(', ')}`);
  }

  // Check for common unescaped special chars in text (heuristic)
  const lines = content.split('\n');
  let resumeItemCount = 0;
  let subheadingCount = 0;
  let projectHeadingCount = 0;

  for (const line of lines) {
    if (/\\resumeItem\{/.test(line)) resumeItemCount++;
    // Negative lookahead (not [^C]) so a line ending exactly at the macro
    // name still counts; only the \resumeSubheadingContinue variant is excluded.
    if (/\\resumeSubheading(?!Continue)/.test(line)) subheadingCount++;
    if (/\\resumeProjectHeading/.test(line)) projectHeadingCount++;
  }

  // Check pdfgentounicode
  if (!content.includes('\\pdfgentounicode=1')) {
    issues.push('Missing \\pdfgentounicode=1 (ATS compatibility)');
  }

  const fileInfo = await stat(absPath);
  const sizeKB = (fileInfo.size / 1024).toFixed(1);

  // Output report as JSON
  const report = {
    file: basename(absPath),
    path: absPath,
    sizeKB: parseFloat(sizeKB),
    counts: {
      resumeItems: resumeItemCount,
      subheadings: subheadingCount,
      projectHeadings: projectHeadingCount,
    },
    issues,
    valid: issues.length === 0,
  };

  // If validation fails, report and exit
  if (issues.length > 0) {
    console.log(JSON.stringify(report, null, 2));
    process.exit(1);
  }

  try {
    report.claimValidation = await enforceRenderedCvClaims(claimOptions.allowUnverifiedClaims ? [content] : extractDocumentSegments(content, absPath), claimOptions);
  } catch (error) {
    report.valid = false;
    report.issues.push(error.message);
    console.log(JSON.stringify(report, null, 2));
    process.exit(1);
  }
  const claimMetadataPath = assertWritableOutput(`${targetPdf}.claims.json`, { root: PROJECT_ROOT });

  // --- Compile .tex → .pdf ---
  // Detect available engine: prefer tectonic, fall back to pdflatex
  let engine = null;
  for (const candidate of ['tectonic', 'pdflatex']) {
    try {
      execFileSync(candidate, ['--version'], { stdio: 'pipe' });
      engine = candidate;
      break;
    } catch { /* not found */ }
  }

  if (!engine) {
    report.compiled = false;
    report.compileError = 'No LaTeX engine found. Install tectonic (brew install tectonic) or pdflatex.';
    console.log(JSON.stringify(report, null, 2));
    process.exit(1);
  }

  report.engine = engine;

  // Ensure the final output directory exists after its path has been checked.
  const targetDir = dirname(targetPdf);
  if (!existsSync(targetDir)) {
    mkdirSync(targetDir, { recursive: true });
  }

  // Compile in a fresh temporary directory so TeX auxiliary files cannot
  // overwrite inputs or create side effects beside an approved CV source.
  const compileDir = await mkdtemp(join(tmpdir(), 'roleforge-latex-'));
  const compileBase = engine === 'tectonic' ? `${texBase}._tectonic` : texBase;
  const compilePath = engine === 'tectonic' ? join(compileDir, `${compileBase}.tex`) : absPath;
  const compiledPdf = join(compileDir, `${compileBase}.pdf`);
  try {
    if (engine === 'tectonic') {
      const patched = content
        .replace(/\\pdfgentounicode\s*=\s*\d+[^\n]*\n?/g, '')
        .replace(/\\input\{glyphtounicode\}[^\n]*\n?/g, '');
      await writeFile(compilePath, patched, { encoding: 'utf-8', flag: 'wx' });
    }

    if (engine === 'tectonic') {
      // Tectonic handles multi-pass automatically; --outdir isolates compiler output.
      execFileSync('tectonic', ['--outdir', compileDir, compilePath], {
        cwd: texDir,
        stdio: 'pipe',
        timeout: 120_000,
      });
    } else {
      const pdflatexArgs = [
        '-no-shell-escape',
        '-interaction=nonstopmode',
        '-halt-on-error',
        `-output-directory=${compileDir}`,
        absPath,
      ];
      // First pass
      execFileSync('pdflatex', pdflatexArgs, { cwd: texDir, stdio: 'pipe', timeout: 120_000 });
      // Second pass (resolves referenceS))
      execFileSync('pdflatex', pdflatexArgs, { cwd: texDir, stdio: 'pipe', timeout: 120_000 });
    }

    report.compiled = true;
  } catch (err) {
    const logPath = join(compileDir, `${compileBase}.log`);
    let latexError = err.message;
    try {
      const log = await readFile(logPath, 'utf-8');
      const errorLines = log.split('\n').filter(l => l.startsWith('!'));
      if (errorLines.length > 0) {
        latexError = errorLines.join('\n');
      }
    } catch { /* no log file */ }

    report.compiled = false;
    report.compileError = latexError;
  }

  // Post-compile: create the requested output exclusively.
  if (report.compiled) {
    try {
      await copyFile(compiledPdf, targetPdf, COPYFILE_EXCL);
      const pdfStat = await stat(targetPdf);
      report.pdf = {
        path: targetPdf,
        sizeKB: parseFloat((pdfStat.size / 1024).toFixed(1)),
      };
      await writeFile(claimMetadataPath, `${JSON.stringify(report.claimValidation, null, 2)}\n`, { encoding: 'utf8', flag: 'wx' });
    } catch (err) {
      report.postCompileError = `Failed to finalize PDF: ${err.message}`;
    }
  }

  await rm(compileDir, { recursive: true, force: true }).catch(() => {});

  console.log(JSON.stringify(report, null, 2));
  process.exit(report.compiled && !report.postCompileError ? 0 : 1);
}

main().catch(error => { console.error(error.message); process.exitCode = 1; });
